// =================== SCENE 2 — THE QUESTION ===================
const QUESTION_TEXT =
  "Find the top 20 reviews of the AirPods Pro on Amazon and tell me what people complain about most.";

const Scene2Question: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const chromeIn = springIn(frame, fps, 0, "GENTLE");
  const driftY = ambientDrift(frame, 2, 140, "scene2-chrome");

  // Realistic typing — start at frame 8, ~1.8 chars/frame (~45 cps) reads natural
  const typeStart = 8;
  const typeRate = 1.6;
  const charsTyped = Math.max(0, Math.min(QUESTION_TEXT.length, Math.floor((frame - typeStart) * typeRate / 1)));
  // Slow it: actually do one char per N frames
  const charsPerFrame = 0.7;
  const typed = Math.max(0, Math.min(QUESTION_TEXT.length, Math.floor((frame - typeStart) * charsPerFrame)));
  const typedText = QUESTION_TEXT.slice(0, typed);
  const isTyping = typed > 0 && typed < QUESTION_TEXT.length;
  const cursorVisible = Math.floor(frame / 12) % 2 === 0;

  // After fully typed (~ frame 8 + 100/0.7 ≈ 151), submit moment
  const fullyTyped = typed >= QUESTION_TEXT.length;
  const submittedFrame = 152;
  const sentIn = springIn(frame, fps, submittedFrame, "SNAPPY");

  return (
    <AbsoluteFill style={{ fontFamily: "'GT Walsheim', Inter, sans-serif" }}>
      <Background />

      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: chromeIn,
          transform: `translateY(${driftY}px)`,
        }}
      >
        <ClaudeChrome>
          {/* Chat body */}
          <div
            style={{
              flex: 1,
              padding: "60px 60px 30px",
              display: "flex",
              flexDirection: "column",
              justifyContent: "flex-end",
            }}
          >
            {/* Sent message bubble appears after submit */}
            {frame >= submittedFrame && (
              <div
                style={{
                  alignSelf: "flex-end",
                  maxWidth: "75%",
                  backgroundColor: COLORS.bg,
                  border: `1px solid ${COLORS.border}`,
                  borderRadius: 22,
                  padding: "24px 32px",
                  opacity: sentIn,
                  transform: `translateY(${interpolate(sentIn, [0, 1], [16, 0])}px)`,
                  fontFamily: "Inter, sans-serif",
                  fontSize: 30,
                  lineHeight: 1.4,
                  color: COLORS.text,
                  letterSpacing: "-0.005em",
                }}
              >
                {QUESTION_TEXT}
              </div>
            )}
          </div>

          {/* Input bar with typing */}
          <div style={{ padding: "0 40px 40px" }}>
            <div
              style={{
                backgroundColor: COLORS.bg,
                border: `1px solid ${fullyTyped && frame < submittedFrame ? COLORS.orange : COLORS.border}`,
                borderRadius: 20,
                padding: "28px 32px",
                display: "flex",
                alignItems: "center",
                gap: 6,
                minHeight: 80,
                transition: "border-color 0.2s",
              }}
            >
              <div
                style={{
                  fontFamily: "Inter, sans-serif",
                  fontSize: 26,
                  color: frame >= submittedFrame ? COLORS.textSubtle : COLORS.text,
                  letterSpacing: "-0.005em",
                  lineHeight: 1.35,
                  flex: 1,
                  opacity: frame >= submittedFrame ? 0.3 : 1,
                }}
              >
                {frame >= submittedFrame ? "" : typedText}
                {frame < submittedFrame && cursorVisible && (
                  <span
                    style={{
                      display: "inline-block",
                      width: 3,
                      height: 28,
                      backgroundColor: COLORS.text,
                      verticalAlign: "middle",
                      marginLeft: 2,
                      marginBottom: -4,
                    }}
                  />
                )}
              </div>
              <div
                style={{
                  fontFamily: "Inter, sans-serif",
                  fontSize: 20,
                  fontWeight: 600,
                  color: fullyTyped ? COLORS.orange : COLORS.textSubtle,
                  padding: "10px 18px",
                  border: `1px solid ${fullyTyped ? COLORS.orange : COLORS.border}`,
                  borderRadius: 12,
